email-when-done.script:
/**
 * Emails the task owner when Status (column D) on the "Tasks" sheet is set to "Done",
 * then writes the date in column E so nobody is emailed twice.
 * Runs from an installable "On edit" trigger on onStatusEdit (see the installation steps).
 */
const SHEET_NAME = 'Tasks';
const TASK_COL = 2; // B: task name
const EMAIL_COL = 3; // C: owner email
const STATUS_COL = 4; // D: status
const NOTIFIED_COL = 5; // E: date the email was sent

function onStatusEdit(e) {
  // Ignore other sheets, the header row, multi-cell pastes and other columns.
  if (!e || !e.range) return;
  const sheet = e.range.getSheet();
  if (sheet.getName() !== SHEET_NAME) return;
  if (e.range.getNumRows() !== 1 || e.range.getNumColumns() !== 1) return;
  const row = e.range.getRow();
  if (row === 1 || e.range.getColumn() !== STATUS_COL) return;
  if (String(e.value).trim() !== 'Done') return;

  const values = sheet.getRange(row, 1, 1, NOTIFIED_COL).getValues()[0];
  const email = String(values[EMAIL_COL - 1]).trim();
  const task = values[TASK_COL - 1];
  // No address, or already notified: do nothing.
  if (!email || values[NOTIFIED_COL - 1]) return;

  MailApp.sendEmail({
    to: email,
    subject: 'Task done: ' + task,
    body: 'The task "' + task + '" (row ' + row + ') was marked as Done.',
  });
  sheet.getRange(row, NOTIFIED_COL).setValue(new Date());
}

archive-daily.script:
/**
 * Every day, moves the rows of "Sheet1" whose Status (column D) is "Archived"
 * to the end of the "Archive" sheet, then deletes them from Sheet1.
 */
const SOURCE = 'Sheet1';
const TARGET = 'Archive';
const STATUS_COL = 4; // D

function archiveRows() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const source = ss.getSheetByName(SOURCE);
  const target = ss.getSheetByName(TARGET);
  if (!source || !target) throw new Error('Sheet "' + SOURCE + '" or "' + TARGET + '" is missing.');

  const data = source.getDataRange().getValues();
  const keep = [data[0]]; // header row
  const moved = [];
  for (let i = 1; i < data.length; i++) {
    if (String(data[i][STATUS_COL - 1]).trim() === 'Archived') moved.push(data[i]);
    else keep.push(data[i]);
  }
  if (moved.length === 0) return;

  // Append first, then rewrite the source, so a failure never loses rows.
  target.getRange(target.getLastRow() + 1, 1, moved.length, moved[0].length).setValues(moved);
  source.clearContents();
  source.getRange(1, 1, keep.length, keep[0].length).setValues(keep);
}

menu-sort.script:
/**
 * Adds a "Tools" menu with an item that sorts the active sheet by column A (A to Z),
 * keeping the header row in place.
 */
function onOpen() {
  SpreadsheetApp.getUi()
    .createMenu('Tools')
    .addItem('Sort by column A', 'sortByColumnA')
    .addToUi();
}

function sortByColumnA() {
  const sheet = SpreadsheetApp.getActiveSheet();
  const lastRow = sheet.getLastRow();
  if (lastRow < 3) return; // nothing to sort
  sheet.getRange(2, 1, lastRow - 1, sheet.getLastColumn()).sort({ column: 1, ascending: true });
}

timestamp-simple.script:
/**
 * Simple trigger: when a cell in column B is edited, writes the current date and time
 * in column C of the same row. Needs no permissions.
 */
const WATCH_COL = 2; // B
const STAMP_COL = 3; // C

function onEdit(e) {
  if (!e || !e.range) return;
  const range = e.range;
  if (range.getColumn() !== WATCH_COL || range.getRow() === 1) return;
  // One stamp per edited row (also works when several rows are pasted at once).
  const stamps = [];
  for (let i = 0; i < range.getNumRows(); i++) stamps.push([new Date()]);
  range.getSheet().getRange(range.getRow(), STAMP_COL, range.getNumRows(), 1).setValues(stamps);
}

form-confirmation.script:
/**
 * On each form response: copies the name and email to the "Contacts" sheet
 * and sends a short confirmation to the respondent.
 * Runs from an installable "On form submit" trigger on handleFormSubmit.
 */
const CONTACTS = 'Contacts';

function handleFormSubmit(e) {
  if (!e || !e.namedValues) return;
  const name = String((e.namedValues['Name'] || [''])[0]).trim();
  const email = String((e.namedValues['Email'] || [''])[0]).trim();
  if (!email) return;

  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(CONTACTS);
  sheet.appendRow([new Date(), name, email]);

  MailApp.sendEmail({
    to: email,
    subject: 'Thanks, we received your answers',
    body: 'Hello ' + (name || 'there') + ',\n\nThank you for filling in the form. We will be in touch soon.',
  });
}

weekly-summary.script:
/**
 * Every week, emails sam@example.com how many rows of "Tickets" have Status (column C) "Open".
 * Runs from a weekly time-driven trigger on sendWeeklySummary.
 */
const RECIPIENT = 'sam@example.com';
const SHEET_NAME = 'Tickets';
const STATUS_COL = 3; // C

function sendWeeklySummary() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_NAME);
  const values = sheet.getRange(2, STATUS_COL, Math.max(sheet.getLastRow() - 1, 1), 1).getValues();
  const open = values.filter((r) => String(r[0]).trim() === 'Open').length;
  MailApp.sendEmail(RECIPIENT, 'Weekly summary: ' + open + ' open tickets', 'There are ' + open + ' rows with Status "Open" in ' + SHEET_NAME + '.');
}

fetch-hourly.script:
/**
 * Every hour, reads the JSON at https://api.example.com/rates and writes the USD rate in B2.
 * Expected JSON: { "rates": { "USD": 1.08, ... } }
 */
const RATES_URL = 'https://api.example.com/rates';

function updateUsdRate() {
  const response = UrlFetchApp.fetch(RATES_URL, { muteHttpExceptions: true });
  if (response.getResponseCode() !== 200) {
    console.warn('Rates request failed with HTTP ' + response.getResponseCode());
    return; // keep the previous value
  }
  const data = JSON.parse(response.getContentText());
  const usd = data && data.rates ? data.rates.USD : undefined;
  if (typeof usd !== 'number') return;
  SpreadsheetApp.getActiveSpreadsheet().getSheets()[0].getRange('B2').setValue(usd);
}

calendar-menu.script:
/**
 * Adds an "Events" menu. Its item creates an all-day event in your default calendar
 * for each row of the active sheet (date in A, title in B) and marks the row in column C.
 */
function onOpen() {
  SpreadsheetApp.getUi().createMenu('Events').addItem('Create calendar events', 'createEvents').addToUi();
}

function createEvents() {
  const sheet = SpreadsheetApp.getActiveSheet();
  const lastRow = sheet.getLastRow();
  if (lastRow < 2) return;
  const rows = sheet.getRange(2, 1, lastRow - 1, 3).getValues();
  const calendar = CalendarApp.getDefaultCalendar();
  rows.forEach((row, i) => {
    const [date, title, done] = row;
    // Skip rows without a real date or title, and rows already created.
    if (!(date instanceof Date) || !title || done) return;
    calendar.createAllDayEvent(String(title), date);
    sheet.getRange(i + 2, 3).setValue('Created');
  });
}

